plugins {
    id("com.android.application")
}

val appId = providers.gradleProperty("morningstar.appId").get()
val appName = providers.gradleProperty("morningstar.appName").get()
val libName = providers.gradleProperty("morningstar.libName").get()

// The app's launcher icons (ADR 0020): a resource directory generated by
// tools/build-android.sh from the app's Cargo.toml, with mipmap-*/ic_launcher*
// and values/ic_launcher_background.xml. It is not part of this template's
// sources. Building here without the script uses what the script last
// generated, and says so plainly if there is nothing.
val iconResDir: File = providers.gradleProperty("morningstar.resDir")
    .map { file(it) }
    .getOrElse(layout.buildDirectory.dir("generated/morningstar/res").get().asFile)

val checkMorningstarIcons = tasks.register("checkMorningstarIcons") {
    val marker = iconResDir.resolve("mipmap-anydpi-v26/ic_launcher.xml")
    doLast {
        if (!marker.isFile) {
            throw GradleException(
                "The app's launcher icons are missing: there is no $marker.\n" +
                    "They are generated from the app's Cargo.toml by tools/build-android.sh " +
                    "(MORNINGSTAR_APP=<package> tools/build-android.sh), which also runs this " +
                    "build. To generate them alone:\n" +
                    "  cargo run -q -p morningstar-devtools --bin morningstar-icon -- " +
                    "<package> --android ${iconResDir}"
            )
        }
    }
}
tasks.named("preBuild") { dependsOn(checkMorningstarIcons) }

android {
    // Namespace of the host's own Java classes; fixed, because the Rust JNI
    // symbols are named after it. The application id is what varies per app.
    namespace = "dev.morningstar.host"
    compileSdk = 36

    defaultConfig {
        applicationId = appId
        // API 24 is the first release where Vulkan 1.0 is part of the platform.
        minSdk = 24
        targetSdk = 36
        versionCode = 1
        versionName = "0.0.1"

        manifestPlaceholders["appName"] = appName
        manifestPlaceholders["libName"] = libName
    }

    sourceSets["main"].res.srcDir(iconResDir)

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }

    buildTypes {
        release {
            isMinifyEnabled = false
        }
    }
}
